BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE ledger_state AS ENUM ('draft','pending_approval','posted','rejected','reversed');
CREATE TYPE intent_side AS ENUM ('buy','sell');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,status text NOT NULL CHECK(status IN('pending','active','suspended')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),display_name text,timezone text NOT NULL DEFAULT 'UTC',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(id smallserial PRIMARY KEY,name text NOT NULL UNIQUE CHECK(name IN('customer','supplier','compliance','finance','admin','super_admin')));
CREATE TABLE user_roles(user_id uuid REFERENCES users(id),role_id smallint REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
INSERT INTO roles(name) VALUES('customer'),('supplier'),('compliance'),('finance'),('admin'),('super_admin');
CREATE TABLE kyc_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),provider_ref text,status text NOT NULL CHECK(status IN('pending','approved','rejected','expired')),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX kyc_cases_user_status_idx ON kyc_cases(user_id,status);
CREATE TABLE sanctions_screening_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kyc_case_id uuid NOT NULL REFERENCES kyc_cases(id),provider_ref text NOT NULL,result text NOT NULL CHECK(result IN('pending','clear','potential_match','blocked')),screened_at timestamptz NOT NULL);
CREATE TABLE legal_entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legal_name text NOT NULL,country_code char(2) NOT NULL,registration_ref text,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),legal_entity_id uuid NOT NULL REFERENCES legal_entities(id),verification_status text NOT NULL DEFAULT 'pending');
CREATE TABLE assets(code text PRIMARY KEY,precision smallint NOT NULL CHECK(precision BETWEEN 0 AND 18),status text NOT NULL CHECK(status IN('disabled','active','suspended')));
INSERT INTO assets VALUES('USD',2,'disabled'),('USDT',6,'disabled'),('DCO_BBL',6,'disabled');
CREATE TABLE wallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'disabled',provider_reference text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wallet_id uuid REFERENCES wallets(id),code text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN('customer_available','customer_reserved','platform_inventory_liability','custody_backing_control','fee_revenue','settlement_control')),asset_code text NOT NULL REFERENCES assets(code),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),state ledger_state NOT NULL DEFAULT 'draft',maker_id uuid NOT NULL REFERENCES users(id),checker_id uuid REFERENCES users(id),reversal_of uuid REFERENCES ledger_transactions(id),idempotency_key text NOT NULL UNIQUE,description text,posted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(checker_id IS NULL OR checker_id<>maker_id));
CREATE TABLE ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid NOT NULL REFERENCES ledger_transactions(id),account_id uuid NOT NULL REFERENCES ledger_accounts(id),asset_code text NOT NULL REFERENCES assets(code),side text NOT NULL CHECK(side IN('debit','credit')),amount_minor numeric(38,0) NOT NULL CHECK(amount_minor>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_entries_tx_idx ON ledger_entries(transaction_id);CREATE INDEX ledger_entries_account_idx ON ledger_entries(account_id,asset_code);
CREATE TABLE trade_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),side intent_side NOT NULL,asset_code text NOT NULL REFERENCES assets(code),quantity_minor numeric(38,0) NOT NULL CHECK(quantity_minor>0),state text NOT NULL DEFAULT 'draft',approval_state text NOT NULL DEFAULT 'not_requested',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quote_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trade_intent_id uuid NOT NULL REFERENCES trade_intents(id),source text NOT NULL,source_timestamp timestamptz NOT NULL,price_minor numeric(38,0) NOT NULL,precision smallint NOT NULL,expires_at timestamptz NOT NULL,raw_payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_code text REFERENCES assets(code),fee_minor numeric(38,0),effective_from timestamptz NOT NULL,effective_to timestamptz,status text NOT NULL DEFAULT 'draft');
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_type text NOT NULL,subject_id uuid NOT NULL,maker_id uuid NOT NULL REFERENCES users(id),checker_id uuid REFERENCES users(id),decision text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,CHECK(checker_id IS NULL OR checker_id<>maker_id));
CREATE TABLE custody_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trade_intent_id uuid REFERENCES trade_intents(id),provider_reference text,status text NOT NULL DEFAULT 'blocked',amount_minor numeric(38,0) NOT NULL,asset_code text NOT NULL REFERENCES assets(code),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlement_instructions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),custody_movement_id uuid REFERENCES custody_movements(id),provider_reference text,status text NOT NULL DEFAULT 'blocked',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE reconciliation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES reconciliation_runs(id),asset_code text REFERENCES assets(code),internal_minor numeric(38,0),provider_minor numeric(38,0),status text NOT NULL);
CREATE TABLE audit_events(id uuid PRIMARY KEY,occurred_at timestamptz NOT NULL,actor_id uuid,action text NOT NULL,subject_type text,subject_id uuid,metadata jsonb NOT NULL DEFAULT '{}',previous_hash char(64) NOT NULL,event_hash char(64) NOT NULL UNIQUE);
CREATE TABLE idempotency_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope text NOT NULL,key_hash char(64) NOT NULL,response_code int,response_body_hash char(64),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,UNIQUE(scope,key_hash));
CREATE TABLE refresh_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash char(64) NOT NULL UNIQUE,rotated_from uuid REFERENCES refresh_sessions(id),expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION deny_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'immutable record';END$$;
CREATE TRIGGER ledger_posted_immutable BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW WHEN (OLD.state='posted') EXECUTE FUNCTION deny_immutable_mutation();
CREATE TRIGGER ledger_entries_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION deny_immutable_mutation();
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_immutable_mutation();
CREATE OR REPLACE FUNCTION assert_posted_transaction_balanced() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.state='posted' AND EXISTS(SELECT 1 FROM (SELECT asset_code,SUM(CASE WHEN side='debit' THEN amount_minor ELSE -amount_minor END) net FROM ledger_entries WHERE transaction_id=NEW.id GROUP BY asset_code) x WHERE x.net<>0) THEN RAISE EXCEPTION 'posted transaction must balance per asset';END IF;RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER ledger_balance_on_post AFTER INSERT OR UPDATE OF state ON ledger_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION assert_posted_transaction_balanced();
CREATE OR REPLACE FUNCTION deny_entry_on_posted_transaction() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF EXISTS(SELECT 1 FROM ledger_transactions WHERE id=NEW.transaction_id AND state='posted') THEN RAISE EXCEPTION 'cannot append to posted transaction';END IF;RETURN NEW;END$$;
CREATE TRIGGER ledger_no_late_entries BEFORE INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION deny_entry_on_posted_transaction();
COMMIT;
